<script setup lang="ts">
import { onMounted, ref } from "vue";
import { http } from "@/utils/http";
type Check = { name: string; status: string; detail: string }; const checks = ref<Check[]>([]); const loading = ref(false); const error = ref(""); const refresh = ref("off");
async function load() { loading.value = true; error.value = ""; try { const [live, ready] = await Promise.allSettled([http.get<any, any>("/health/live"), http.get<any, any>("/health/ready")]); checks.value = [{ name: "Application / API", status: live.status === "fulfilled" ? live.value?.status || "UP" : "DOWN", detail: "应用存活探针" }, { name: "PostgreSQL", status: ready.status === "fulfilled" ? ready.value?.status || "UP" : "DOWN", detail: "数据库就绪探针" }]; } catch (e: any) { error.value = e?.message || "健康检查失败"; } finally { loading.value = false; } }
onMounted(load);
</script>
<template><main class="p-4 md:p-6"><div class="flex justify-between items-start mb-6"><div><h1 class="text-2xl font-semibold">系统健康与告警</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">查看后端定义的健康状态和组件探针结果。</p></div><div class="flex gap-2"><el-tag>开发环境</el-tag><el-select v-model="refresh" class="w-32"><el-option label="自动刷新：关闭" value="off"/><el-option label="30 秒" value="30"/><el-option label="1 分钟" value="60"/><el-option label="5 分钟" value="300"/></el-select><el-button :loading="loading" @click="load">刷新</el-button></div></div><el-alert :title="checks.some(item => item.status === 'DOWN') ? '系统异常' : '系统健康'" :type="checks.some(item => item.status === 'DOWN') ? 'error' : 'success'" show-icon :closable="false" class="mb-5"/><el-skeleton v-if="loading" :rows="8" animated/><div v-else class="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4"><el-card v-for="item in checks" :key="item.name" shadow="never"><div class="flex justify-between"><span class="font-medium">{{ item.name }}</span><el-tag :type="item.status === 'UP' ? 'success' : 'danger'">{{ item.status }}</el-tag></div><p class="text-sm text-[var(--el-text-color-secondary)] mt-3">{{ item.detail }}</p><div class="text-xs text-[var(--el-text-color-secondary)] mt-4">最近检查：{{ new Date().toLocaleString() }}</div></el-card><el-card shadow="never"><div class="font-medium">资源指标</div><el-empty description="暂无 CPU、Memory、Queue Sample" :image-size="70"/></el-card><el-card shadow="never"><div class="font-medium">告警</div><el-empty description="暂无告警数据" :image-size="70"/></el-card></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="mt-4"/></main></template>
